Для входа нужен **`ton_proof`**: кошелёк подписывает одноразовый challenge, а сервер проверяет подпись и её связь с адресом. Само подключение кошелька авторизацией не является. [Документация TON](https://docs.ton.org/applications/ton-connect/how-to/ton-proof).

Ниже пример для **mainnet**, общего HTTPS origin фронтенда и API, Redis и серверной cookie-сессии. Поддерживаются V3R2, V4R2, V5R1 и WalletTg; неизвестные контракты отклоняются.

Зависимости:

```bash
# Фронтенд
npm i @tonconnect/ui-react

# Бэкенд
npm i express@5 express-session connect-redis redis zod @ton/ton
```

Фронтенд:

```tsx
import { useEffect, useRef, useState } from "react";
import {
  TonConnectUIProvider,
  useIsConnectionRestored,
  useTonConnectUI,
} from "@tonconnect/ui-react";

type User = { address: string; network: string };

async function api(path: string, body?: unknown) {
  const response = await fetch(path, {
    method: body === undefined ? "GET" : "POST",
    credentials: "same-origin",
    cache: "no-store",
    headers: { "Content-Type": "application/json" },
    body: body === undefined ? undefined : JSON.stringify(body),
  });

  if (path === "/api/me" && response.status === 401) return null;
  if (!response.ok) throw new Error("Запрос отклонён. Попробуйте войти ещё раз.");
  return response.json();
}

function WalletLogin() {
  const [ui] = useTonConnectUI();
  const restored = useIsConnectionRestored();
  const expectedPayload = useRef<string | null>(null);

  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [preparing, setPreparing] = useState(false);
  const [checking, setChecking] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    let alive = true;

    void api("/api/me")
      .then(value => { if (alive) setUser(value); })
      .catch(() => { if (alive) setError("Не удалось проверить сессию"); })
      .finally(() => { if (alive) setLoading(false); });

    const unsubscribe = ui.onStatusChange(async wallet => {
      const expected = expectedPayload.current;
      if (!wallet || !expected) return;

      const item = wallet.connectItems?.tonProof;
      if (!item || !("proof" in item)) {
        expectedPayload.current = null;
        setError("Кошелёк не предоставил ton_proof");
        return;
      }

      // Игнорируем старые события, включая восстановленное соединение.
      if (item.proof.payload !== expected) return;
      expectedPayload.current = null;

      setChecking(true);
      try {
        const authenticated = await api("/api/ton/verify", {
          address: wallet.account.address,
          network: wallet.account.chain,
          publicKey: wallet.account.publicKey,
          walletStateInit: wallet.account.walletStateInit,
          proof: item.proof,
        });

        if (alive) {
          setUser(authenticated);
          setError("");
        }
      } catch {
        if (alive) setError("Вход отклонён. Переподключите кошелёк.");
      } finally {
        if (alive) setChecking(false);
      }
    });

    return () => {
      alive = false;
      unsubscribe();
    };
  }, [ui]);

  async function login() {
    setPreparing(true);
    setError("");
    expectedPayload.current = null;

    try {
      // Новому входу нужен свежий proof.
      if (ui.connected) await ui.disconnect();

      ui.setConnectRequestParameters({ state: "loading" });

      const { payload } = await api("/api/ton/challenge", {});
      expectedPayload.current = payload;

      ui.setConnectRequestParameters({
        state: "ready",
        value: { tonProof: payload },
      });

      // Авторизация завершится в onStatusChange после ответа сервера.
      await ui.openModal();
    } catch {
      expectedPayload.current = null;
      ui.setConnectRequestParameters(null);
      setError("Не удалось начать вход");
    } finally {
      setPreparing(false);
    }
  }

  if (user) return <p>Выполнен вход: {user.address}</p>;

  return (
    <div>
      <button
        disabled={!restored || loading || preparing || checking}
        onClick={login}
      >
        {checking ? "Проверяем подпись…" : "Войти через TON"}
      </button>
      {error && <p role="alert">{error}</p>}
    </div>
  );
}

export default function App() {
  return (
    <TonConnectUIProvider
      manifestUrl="https://app.example.com/tonconnect-manifest.json"
    >
      <WalletLogin />
    </TonConnectUIProvider>
  );
}
```

По публичному URL манифеста должен отдаваться JSON с вашими адресами:

```json
{
  "url": "https://app.example.com",
  "name": "Наше приложение",
  "iconUrl": "https://app.example.com/icon.png"
}
```

Бэкенд, Node.js ESM. Переменные окружения: `APP_ORIGIN`, `REDIS_URL`, случайный `SESSION_SECRET` минимум из 32 байт; `TONCENTER_API_KEY` — при необходимости. Пример предполагает локальный TLS reverse proxy, который направляет `/api/*` на `127.0.0.1:3000`.

```js
import express from "express";
import session from "express-session";
import { RedisStore } from "connect-redis";
import { createClient } from "redis";
import { createHash, randomBytes } from "node:crypto";
import { z } from "zod";
import {
  Address, Cell, contractAddress, loadStateInit, domainSignVerify,
  TonClient, WalletContractV3R2, WalletContractV4, WalletContractV5R1,
} from "@ton/ton";

const appURL = new URL(process.env.APP_ORIGIN);
const ORIGIN = appURL.origin;
const DOMAIN = appURL.host;
const NETWORK = "-239";
const TTL = 300;
const secret = process.env.SESSION_SECRET;

if (appURL.protocol !== "https:" || !secret || secret.length < 32) {
  throw new Error("Configure HTTPS APP_ORIGIN and SESSION_SECRET");
}

const redis = createClient({ url: process.env.REDIS_URL });
redis.on("error", console.error);
await redis.connect();

// Только доверенный mainnet RPC, адрес не берём из запроса.
const rpc = new TonClient({
  endpoint: "https://toncenter.com/api/v2/jsonRPC",
  apiKey: process.env.TONCENTER_API_KEY,
  timeout: 10_000,
});

const app = express();
app.set("trust proxy", "loopback");

app.use("/api", (req, res, next) => {
  res.set("Cache-Control", "no-store");
  if (req.method === "POST" && req.get("origin") !== ORIGIN) {
    return res.status(403).json({ error: "Forbidden origin" });
  }
  next();
});

app.use(express.json({ limit: "48kb" }));
app.use(session({
  name: "__Host-ton.sid",
  secret,
  store: new RedisStore({ client: redis, prefix: "app:session:" }),
  resave: false,
  saveUninitialized: false,
  cookie: {
    secure: true,
    httpOnly: true,
    sameSite: "lax",
    path: "/",
    maxAge: 8 * 60 * 60 * 1000,
  },
}));

const sessionCall = (req, method) => new Promise((resolve, reject) => {
  req.session[method](error => error ? reject(error) : resolve());
});

const Timestamp = z.union([
  z.number(),
  z.string().regex(/^\d{1,16}$/),
]).transform(Number).refine(n => Number.isSafeInteger(n) && n >= 0);

const Input = z.object({
  address: z.string().min(1).max(128),
  network: z.literal(NETWORK),
  publicKey: z.string().regex(/^[0-9a-fA-F]{64}$/).optional(),
  walletStateInit: z.string().min(1).max(32768),
  proof: z.object({
    timestamp: Timestamp,
    domain: z.object({
      value: z.string().max(128),
      lengthBytes: z.number().int().min(0).max(128),
    }),
    payload: z.string().regex(/^[0-9a-f]{64}$/),
    signature: z.string().regex(/^[A-Za-z0-9+/]{86}==$/),
  }),
});

function requireValid(condition) {
  if (!condition) throw new Error("Invalid wallet proof");
}

const fixedWallets = [
  [WalletContractV3R2, 64],
  [WalletContractV4, 64],
  [WalletContractV5R1, 65],
].map(([Contract, skip]) => ({
  hash: Contract.create({
    workchain: 0,
    publicKey: Buffer.alloc(32),
  }).init.code.hash().toString("hex"),
  skip,
}));

const WALLET_TG_HASH =
  "9149ae51c1e4689710cebf7830297b16acfbadb363a920a537893e7ffeeca768";

async function resolvePublicKey(init, address) {
  const hash = init.code?.hash().toString("hex");
  const fixed = fixedWallets.find(wallet => wallet.hash === hash);

  if (fixed && init.data) {
    const data = init.data.beginParse();
    data.skip(fixed.skip);
    return data.loadBuffer(32);
  }

  // У WalletTg начальный ключ может устареть после ротации.
  requireValid(hash === WALLET_TG_HASH);

  const provider = rpc.provider(address, null);
  const { state } = await provider.getState();
  requireValid(state.type === "active" && state.code);

  const code = Cell.fromBoc(state.code);
  requireValid(
    code.length === 1 &&
    code[0].hash().toString("hex") === WALLET_TG_HASH
  );

  const { stack } = await provider.get("get_public_key", []);
  const key = stack.readBigNumber();
  requireValid(key >= 0n && key < (1n << 256n));

  return Buffer.from(key.toString(16).padStart(64, "0"), "hex");
}

const sha256 = bytes => createHash("sha256").update(bytes).digest();

function proofDigest(address, proof) {
  const wc = Buffer.alloc(4);
  wc.writeInt32BE(address.workChain);

  const domain = Buffer.from(proof.domain.value, "utf8");
  requireValid(proof.domain.lengthBytes === domain.length);

  const domainLength = Buffer.alloc(4);
  domainLength.writeUInt32LE(domain.length);

  const timestamp = Buffer.alloc(8);
  timestamp.writeBigUInt64LE(BigInt(proof.timestamp));

  const message = Buffer.concat([
    Buffer.from("ton-proof-item-v2/", "utf8"),
    wc,
    address.hash,
    domainLength,
    domain,
    timestamp,
    Buffer.from(proof.payload, "utf8"),
  ]);

  return sha256(Buffer.concat([
    Buffer.from([0xff, 0xff]),
    Buffer.from("ton-connect", "utf8"),
    sha256(message),
  ]));
}

async function verifyProof(input) {
  const { proof } = input;
  const now = Math.floor(Date.now() / 1000);

  requireValid(proof.domain.value === DOMAIN);
  requireValid(
    proof.timestamp >= now - TTL &&
    proof.timestamp <= now + 30
  );

  const address = Address.parse(input.address);
  const slice = Cell.fromBase64(input.walletStateInit).beginParse();
  const init = loadStateInit(slice);
  slice.endParse();

  requireValid(
    contractAddress(address.workChain, init).equals(address)
  );

  const publicKey = await resolvePublicKey(init, address);

  // Клиентский publicKey используется только для сверки.
  if (input.publicKey !== undefined) {
    requireValid(publicKey.equals(Buffer.from(input.publicKey, "hex")));
  }

  requireValid(domainSignVerify({
    data: proofDigest(address, proof),
    signature: Buffer.from(proof.signature, "base64"),
    publicKey,
    domain: { type: "empty" }, // Mainnet.
  }));

  return { address: address.toRawString(), network: NETWORK };
}

const challengeKey = payload => `app:ton-proof:${payload}`;

// Сравнение владельца и удаление выполняются атомарно.
const consumeChallenge = `
  if redis.call("GET", KEYS[1]) == ARGV[1] then
    return redis.call("DEL", KEYS[1])
  end
  return 0
`;

app.post("/api/ton/challenge", async (req, res) => {
  req.session.loginPending = true;
  await sessionCall(req, "save");

  const payload = randomBytes(32).toString("hex");
  const created = await redis.set(
    challengeKey(payload),
    req.sessionID,
    { EX: TTL, NX: true },
  );
  if (created !== "OK") throw new Error("Challenge creation failed");

  res.json({ payload });
});

app.post("/api/ton/verify", async (req, res) => {
  const parsed = Input.safeParse(req.body);
  if (!parsed.success) {
    return res.status(400).json({ error: "Invalid request" });
  }

  const input = parsed.data;
  const key = challengeKey(input.proof.payload);

  if (
    !req.session.loginPending ||
    await redis.get(key) !== req.sessionID
  ) {
    return res.status(401).json({ error: "Challenge expired or invalid" });
  }

  let user;
  try {
    user = await verifyProof(input);
  } catch {
    return res.status(401).json({ error: "Proof rejected" });
  }

  const consumed = await redis.eval(consumeChallenge, {
    keys: [key],
    arguments: [req.sessionID],
  });

  if (consumed !== 1) {
    return res.status(401).json({ error: "Challenge already used or expired" });
  }

  // Защита от фиксации сессии.
  await sessionCall(req, "regenerate");
  req.session.user = user;
  await sessionCall(req, "save");

  res.json(user);
});

app.get("/api/me", (req, res) => {
  if (!req.session.user) {
    return res.status(401).json({ error: "Authentication required" });
  }
  res.json(req.session.user);
});

app.use((error, req, res, next) => {
  console.error(error);
  res.status(error.status ?? 500).json({ error: "Request failed" });
});

app.listen(3000, "127.0.0.1");
```

Сервер связывает **адрес → StateInit → известный код кошелька → ключ → подпись**. Для WalletTg дополнительно проверяет активный код и получает текущий ключ из блокчейна. Произвольному `get_public_key` доверять нельзя. [Правила извлечения ключа](https://docs.ton.org/applications/ton-connect/how-to/sign-data#extracting-the-public-key).

Challenge действует пять минут, привязан к серверной сессии браузера и погашается один раз, включая параллельные запросы. После входа защищённые обработчики должны брать пользователя из `req.session.user`. Сеть не входит в подпись `ton_proof`, поэтому здесь сервер принимает только mainnet. [Спецификация](https://github.com/ton-blockchain/ton-connect/blob/main/spec/connect.md#address-proof-signature-ton_proof).

